#!/usr/bin/env python3
# AUTO-GENERATED: standalone USB file explorer with embedded UI and help.
# ======================================================================
# usb_tool.py — проводник файлов ESP32 по USB-проводу
# ======================================================================
# Запускает локальный HTTP-сервер с тем же UI, что и на плате, но
# работает через COM-порт с помощью mpremote. Доступны все файлы
# внутренней ФС и смонтированная SD-карта (/sd).
#
# ВАЖНО: mpremote при каждом запросе прерывает приложение на плате
# (переводит её в REPL). Это нормально для режима управления файлами.
# Кнопка "Перезагрузить" в UI перезапускает плату.
#
# Запуск: python usb_tool.py --port COM6 --http-port 8081
# ======================================================================
import argparse
import base64
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, urlparse

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
INDEX = os.path.join(ROOT, 'src', 'apps', 'system', 'explorer', 'utils', 'index.html')
MAX_EDIT = 1024 * 1024
MPREMOTE = shutil.which('mpremote') or 'mpremote'

# В автономной копии, которую можно скачать с платы, здесь лежит
# base64 от index.html.
EMBEDDED_INDEX_B64 = ""
# То же для страницы с инструкцией usb.html.
EMBEDDED_USB_B64 = ""


class DeviceError(Exception):
    pass


def _index_bytes():
    """UI из файла рядом с репозиторием либо из встроенной копии."""
    try:
        with open(INDEX, 'rb') as f:
            return f.read()
    except OSError:
        if EMBEDDED_INDEX_B64:
            return base64.b64decode(EMBEDDED_INDEX_B64)
        raise DeviceError('index.html not found: %s' % INDEX)


def _usb_help_bytes():
    """Страница инструкции из файла либо из встроенной копии."""
    path = os.path.join(ROOT, 'src', 'apps', 'system', 'explorer',
                        'utils', 'usb.html')
    try:
        with open(path, 'rb') as f:
            return f.read()
    except OSError:
        if EMBEDDED_USB_B64:
            return base64.b64decode(EMBEDDED_USB_B64)
        raise DeviceError('usb.html not found: %s' % path)


def _parent(path):
    if not path or path == '/':
        return None
    p = path.rstrip('/')
    i = p.rfind('/')
    return '/' if i <= 0 else p[:i]


def _join(a, b):
    return a.rstrip('/') + '/' + b


class Device:
    """Доступ к файловой системе платы через mpremote."""

    def __init__(self, port):
        self.port = port
        self.lock = threading.Lock()

    def _run(self, args, timeout=180):
        cmd = [MPREMOTE, 'connect', self.port] + args
        try:
            p = subprocess.run(cmd, capture_output=True, timeout=timeout)
        except FileNotFoundError:
            raise DeviceError('mpremote not found in PATH')
        except subprocess.TimeoutExpired:
            raise DeviceError('mpremote timeout')
        if p.returncode != 0:
            err = p.stderr.decode('utf-8', 'replace').strip()
            out = p.stdout.decode('utf-8', 'replace').strip()
            raise DeviceError(err or out or ('mpremote exit %d' % p.returncode))
        return p.stdout

    def _exec(self, code, timeout=180):
        with self.lock:
            return self._run(['exec', code], timeout).decode('utf-8', 'replace')

    def _json(self, code, timeout=180):
        out = self._exec(code, timeout)
        for line in reversed(out.strip().splitlines()):
            line = line.strip()
            if line.startswith('{') or line.startswith('['):
                try:
                    return json.loads(line)
                except ValueError:
                    continue
        raise DeviceError('bad JSON from device: %r' % out[-300:])

    # ---- операции ----

    def listdir(self, path):
        code = (
            "import os,json\n"
            "p=%r\n"
            "out=[]\n"
            "for e in os.ilistdir(p):\n"
            " n=e[0]; d=bool(e[1]&0x4000)\n"
            " if d: s=0\n"
            " elif len(e)>3: s=e[3]\n"
            " else:\n"
            "  try: s=os.stat(p+'/'+n)[6]\n"
            "  except Exception: s=0\n"
            " out.append({'name':n,'dir':d,'size':s})\n"
            "out.sort(key=lambda x:(not x['dir'],x['name'].lower()))\n"
            "print(json.dumps(out))\n"
        ) % path
        return self._json(code)

    def statvfs(self, path):
        code = (
            "import os,json\n"
            "s=os.statvfs(%r)\n"
            "print(json.dumps([s[0]*s[3],s[0]*s[2]]))\n"
        ) % path
        vals = self._json(code)
        return vals[0], vals[1]

    def has_sd(self):
        out = self._exec(
            "try:\n"
            " import apps.system.explorer.utils.mounts as m\n"
            " print('SD' if m.mounted() else 'NO')\n"
            "except Exception:\n"
            " print('NO')\n"
        )
        return 'SD' in out

    def info(self):
        roots = [{'id': '/', 'label': 'Internal'}]
        if self.has_sd():
            roots.append({'id': '/sd', 'label': 'SD card'})
        free, total = self.statvfs('/')
        info = {
            'ok': True,
            'title': 'ESP32 Files (USB)',
            'usb': True,
            'roots': roots,
            'free': free,
            'total': total,
            'size': total,
            'mode': 'usb',
            'ssid': '',
            'ip': '',
            'host': 'USB',
            'dns': False,
            'sd': len(roots) > 1,
        }
        if len(roots) > 1:
            sf, st = self.statvfs('/sd')
            info['sd_free'] = sf
            info['sd_total'] = st
            info['sd_size'] = st
        return info

    def stat(self, path):
        code = (
            "import os,json\n"
            "s=os.stat(%r)\n"
            "print(json.dumps([bool(s[0]&0x4000),s[6]]))\n"
        ) % path
        v = self._json(code)
        return bool(v[0]), int(v[1])

    def read_range(self, path, offset, length):
        # mpremote fs cat не умеет бинарные файлы (UnicodeError), поэтому
        # читаем base64-фрагментами через exec.
        code = (
            "import binascii\n"
            "f=open(%r,'rb')\n"
            "f.seek(%d)\n"
            "d=f.read(%d)\n"
            "f.close()\n"
            "print(binascii.b2a_base64(d).decode().strip())\n"
        ) % (path, offset, length)
        out = self._exec(code, timeout=600)
        line = ''
        for ln in out.splitlines():
            if ln.strip():
                line = ln.strip()
        if not line:
            return b''
        return base64.b64decode(line)

    def read(self, path):
        is_dir, size = self.stat(path)
        if is_dir:
            raise DeviceError('is a directory')
        parts = []
        off = 0
        while off < size:
            chunk = self.read_range(path, off, min(65536, size - off))
            if not chunk:
                break
            parts.append(chunk)
            off += len(chunk)
        return b''.join(parts)

    def write(self, path, data):
        fd, tmp = tempfile.mkstemp(prefix='esp32_', suffix='.bin')
        try:
            with os.fdopen(fd, 'wb') as f:
                f.write(data)
            with self.lock:
                self._run(['fs', 'cp', tmp, ':' + path], timeout=600)
        finally:
            try:
                os.unlink(tmp)
            except OSError:
                pass

    def remove(self, path, recursive=False):
        if recursive:
            code = (
                "import os\n"
                "def _rm(p):\n"
                " try:\n"
                "  if os.stat(p)[0]&0x4000:\n"
                "   for e in os.ilistdir(p): _rm(p+'/'+e[0])\n"
                "   os.rmdir(p)\n"
                "  else:\n"
                "   os.remove(p)\n"
                " except OSError:\n"
                "  pass\n"
                "_rm(%r)\n"
            ) % path
        else:
            code = (
                "import os\n"
                "p=%r\n"
                "if os.stat(p)[0]&0x4000:\n"
                " os.rmdir(p)\n"
                "else:\n"
                " os.remove(p)\n"
            ) % path
        self._exec(code)

    def mkdir(self, path):
        self._exec("import os\nos.mkdir(%r)\n" % path)

    def rename(self, old, new):
        code = (
            "import os\n"
            "src=%r; dst=%r\n"
            "try:\n"
            " st=os.stat(dst)\n"
            " if not (st[0]&0x4000): os.remove(dst)\n"
            "except OSError:\n"
            " pass\n"
            "os.rename(src,dst)\n"
        ) % (old, new)
        self._exec(code)

    def reset(self):
        with self.lock:
            self._run(['reset'], timeout=60)


class Handler(BaseHTTPRequestHandler):
    device = None
    server_version = 'ESP32Files/1.0'

    def log_message(self, *args):
        pass

    # ---- ответы ----

    def _send(self, code, body, ctype, headers=None):
        try:
            self.send_response(code)
            self.send_header('Content-Type', ctype)
            self.send_header('Content-Length', str(len(body)))
            self.send_header('Cache-Control', 'no-store')
            for k, v in (headers or {}).items():
                self.send_header(k, v)
            self.end_headers()
            self.wfile.write(body)
        except (BrokenPipeError, ConnectionResetError):
            pass

    def _json(self, obj, code=200):
        self._send(code, json.dumps(obj).encode('utf-8'),
                   'application/json; charset=utf-8')

    def _err(self, msg, code=500):
        self._json({'ok': False, 'error': str(msg)}, code)

    # ---- GET ----

    def do_GET(self):
        u = urlparse(self.path)
        q = parse_qs(u.query)
        try:
            if u.path in ('/', '/index.html'):
                self._send(200, _index_bytes(), 'text/html; charset=utf-8')
            elif u.path in ('/usb', '/usb/'):
                self._send(200, _usb_help_bytes(), 'text/html; charset=utf-8')
            elif u.path == '/favicon.ico':
                self._send(204, b'', 'image/x-icon')
            elif u.path == '/api/ping':
                self._json({'ok': True})
            elif u.path == '/api/usb-tool':
                with open(os.path.abspath(__file__), 'rb') as f:
                    data = f.read()
                self._send(200, data, 'text/x-python; charset=utf-8', {
                    'Content-Disposition':
                        'attachment; filename="file_explorer.py"',
                })
            elif u.path == '/api/info':
                self._json(self.device.info())
            elif u.path == '/api/list':
                path = q.get('path', ['/'])[0]
                entries = self.device.listdir(path)
                free, total = self.device.statvfs(path)
                self._json({
                    'ok': True,
                    'path': path,
                    'parent': _parent(path),
                    'entries': entries,
                    'free': free,
                    'total': total,
                    'size': total,
                })
            elif u.path == '/api/file':
                path = q.get('path', [''])[0]
                if not path:
                    raise ValueError('path required')
                is_dir, size = self.device.stat(path)
                if is_dir:
                    raise ValueError('is a directory')
                if size > MAX_EDIT:
                    self._err('too large: max %d bytes' % MAX_EDIT, 413)
                    return
                data = self.device.read(path)
                if b'\x00' in data[:4096]:
                    self._err('binary file', 415)
                    return
                self._send(200, data, 'text/plain; charset=utf-8')
            elif u.path == '/api/download':
                path = q.get('path', [''])[0]
                if not path:
                    raise ValueError('path required')
                is_dir, size = self.device.stat(path)
                if is_dir:
                    raise ValueError('is a directory')
                name = path.rstrip('/').rsplit('/', 1)[-1]
                start, end = 0, size - 1
                code = 200
                rng = self.headers.get('Range')
                if rng and rng.startswith('bytes='):
                    spec = rng[6:].split(',')[0].strip()
                    try:
                        a, b = spec.split('-', 1)
                        if a == '':
                            n = int(b)
                            start = max(0, size - n)
                            end = size - 1
                        else:
                            start = int(a)
                            if b:
                                end = min(int(b), size - 1)
                        if start >= size or start > end:
                            raise ValueError('range')
                        code = 206
                    except Exception:
                        start, end, code = 0, size - 1, 200
                length = max(0, end - start + 1)
                try:
                    self.send_response(code)
                    self.send_header('Content-Type', 'application/octet-stream')
                    self.send_header('Content-Length', str(length))
                    self.send_header('Accept-Ranges', 'bytes')
                    if code == 206:
                        self.send_header(
                            'Content-Range',
                            'bytes %d-%d/%d' % (start, end, size))
                    self.send_header('Content-Disposition',
                                     'attachment; filename="%s"' % name)
                    self.send_header('Cache-Control', 'no-store')
                    self.end_headers()
                    off = start
                    remaining = length
                    while remaining > 0:
                        chunk = self.device.read_range(
                            path, off, min(65536, remaining))
                        if not chunk:
                            break
                        self.wfile.write(chunk)
                        off += len(chunk)
                        remaining -= len(chunk)
                except (BrokenPipeError, ConnectionResetError):
                    pass
            else:
                self._err('not found', 404)
        except Exception as e:
            self._err(e)

    # ---- POST ----

    def do_POST(self):
        u = urlparse(self.path)
        q = parse_qs(u.query)
        try:
            if u.path == '/api/upload':
                n = int(self.headers.get('Content-Length') or 0)
                if n <= 0:
                    raise ValueError('empty body')
                path = q.get('path', ['/'])[0]
                name = q.get('name', [''])[0]
                if not name:
                    raise ValueError('name required')
                name = name.replace('/', '_')
                data = self.rfile.read(n)
                self.device.write(_join(path, name), data)
                self._json({'ok': True, 'name': name, 'size': len(data)})
                return
            if u.path == '/api/save':
                n = int(self.headers.get('Content-Length') or 0)
                if n < 0 or n > MAX_EDIT:
                    self._err('too large: max %d bytes' % MAX_EDIT, 413)
                    return
                path = q.get('path', [''])[0]
                if not path or path == '/':
                    raise ValueError('bad path')
                data = self.rfile.read(n)
                if len(data) != n:
                    raise ValueError('incomplete save')
                self.device.write(path, data)
                self._json({'ok': True, 'path': path, 'size': len(data)})
                return
            if u.path == '/api/delete':
                path = q.get('path', [''])[0]
                rec = q.get('recursive', ['0'])[0] in ('1', 'true', 'yes')
                self.device.remove(path, rec)
                self._json({'ok': True})
                return
            if u.path == '/api/mkdir':
                path = q.get('path', [''])[0]
                self.device.mkdir(path)
                self._json({'ok': True})
                return
            if u.path == '/api/rename':
                path = q.get('path', [''])[0]
                new = q.get('to', [''])[0]
                self.device.rename(path, new)
                self._json({'ok': True})
                return
            if u.path == '/api/reset':
                # Ответ отправляем до перезагрузки, иначе браузер
                # показывает ошибку сети вместо подтверждения.
                self._json({'ok': True, 'reset': True})
                threading.Thread(target=self.device.reset, daemon=True).start()
                return
            self._err('not found', 404)
        except Exception as e:
            self._err(e)


def _detect_port():
    try:
        out = subprocess.run([MPREMOTE, 'connect', 'list'],
                             capture_output=True, timeout=15)
        text = out.stdout.decode('utf-8', 'replace')
        m = re.search(r'\b(COM\d+|/dev/ttyACM\d+|/dev/ttyUSB\d+)\b', text)
        if m:
            return m.group(1)
    except Exception:
        pass
    try:
        from serial.tools import list_ports
        for p in list_ports.comports():
            desc = (p.description or '').upper()
            if p.vid == 0x303A or 'ESP' in desc or 'CP210' in desc or 'CH340' in desc:
                return p.device
        ports = list(list_ports.comports())
        if ports:
            return ports[0].device
    except Exception:
        pass
    return 'COM6'


def main():
    ap = argparse.ArgumentParser(
        description='ESP32 file explorer over USB (mpremote)')
    ap.add_argument('--port', default='', help='serial port, e.g. COM6')
    ap.add_argument('--http-port', type=int, default=8081,
                    help='local HTTP port (default 8081)')
    ap.add_argument('--no-browser', action='store_true',
                    help='do not open a browser')
    args = ap.parse_args()

    port = args.port or _detect_port()
    Handler.device = Device(port)

    httpd = ThreadingHTTPServer(('127.0.0.1', args.http_port), Handler)
    url = 'http://127.0.0.1:%d/' % args.http_port

    print('ESP32 USB file explorer')
    print('  port :', port)
    print('  open :', url)
    print('  stop : Ctrl+C')
    print('  note : each operation interrupts the running app on the board;')
    print('         use the Reboot button in the UI when finished.')
    if not args.no_browser:
        try:
            import webbrowser
            webbrowser.open(url)
        except Exception:
            pass

    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        print('\nstopped')
    finally:
        httpd.server_close()


if __name__ == '__main__':
    main()
